package com.porter.stashmanager.planner;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;

import java.io.IOException;
import java.io.InputStream;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Block -> item table for one Minecraft version (resource {@code block-items/<version>.json}, generated by
 * {@code dev/block-items}), and the conversion of a {@link Schematic}'s block states into a {@link MaterialList}.
 *
 * <p>Rules: {@code lower} (count only half=lower), {@code head} (count only part=head), {@code slab} (type=double
 * counts 2), {@code amount:<prop>} (the property value is the count), {@code pot:<item>} / {@code with:<item>} (the
 * block's item plus one of that item), {@code fluid} (source blocks become buckets), {@code ignore}. Waterlogging is
 * ignored. Multiface blocks (vines, glow lichen, sculk vein) count 1 per block whatever their faces.
 */
public final class BlockItems {
    /** The bundled tables, oldest first. */
    public static final List<String> VERSIONS = List.of("1.21.4", "1.21.11");
    public static final int MAX_UNKNOWN = 500;

    /** Renamed block ids, old -> new. Applied only when the table lacks the id and has the target (so both directions work). */
    static final Map<String, String> ALIASES = Map.ofEntries(
        Map.entry("minecraft:grass", "minecraft:short_grass"),          // 1.20.3
        Map.entry("minecraft:grass_path", "minecraft:dirt_path"),       // 1.17
        Map.entry("minecraft:chain", "minecraft:iron_chain"),           // 1.21.9
        Map.entry("minecraft:iron_chain", "minecraft:chain"),           // a newer schematic against an older table
        Map.entry("minecraft:sign", "minecraft:oak_sign"),              // 1.14
        Map.entry("minecraft:wall_sign", "minecraft:oak_wall_sign"));   // 1.14

    private static final Map<String, String> FLUID_BUCKETS = Map.of("minecraft:water", "minecraft:water_bucket", "minecraft:lava", "minecraft:lava_bucket");
    private static final Map<String, BlockItems> CACHE = new ConcurrentHashMap<>();

    /** One block's entry: the item to count (null for ignore/fluid) and the rule (null for one item per block). */
    public record Entry(String item, String rule) {
    }

    private final String version;
    private final int dataVersion;
    private final Map<String, Entry> blocks;
    private final Map<String, Integer> maxStack;

    BlockItems(String version, int dataVersion, Map<String, Entry> blocks, Map<String, Integer> maxStack) {
        this.version = version;
        this.dataVersion = dataVersion;
        this.blocks = Map.copyOf(blocks);
        this.maxStack = Map.copyOf(maxStack);
    }

    // ---------- loading ----------

    /**
     * The table for {@code mcVersion}: the oldest bundled version not older than it (a newer table still has every
     * older block), or the newest table when it is newer than all of them.
     */
    public static BlockItems forVersion(String mcVersion) {
        int[] want = parts(mcVersion);
        for (String v : VERSIONS) if (compare(parts(v), want) >= 0) return load(v);
        return latest();
    }

    /**
     * The table with the lowest data version not below {@code dataVersion} (a 1.21.8 file gets the 1.21.11 table, which
     * knows the blocks added since 1.21.4), or the newest table when the file is newer than all of them.
     */
    public static BlockItems forDataVersion(int dataVersion) {
        for (String v : VERSIONS) {
            BlockItems t = load(v);
            if (t.dataVersion >= dataVersion) return t;
        }
        return latest();
    }

    /** The newest bundled table. */
    public static BlockItems latest() {
        return load(VERSIONS.get(VERSIONS.size() - 1));
    }

    static BlockItems load(String version) {
        return CACHE.computeIfAbsent(version, BlockItems::readResource);
    }

    private static BlockItems readResource(String version) {
        String path = "/block-items/" + version + ".json";
        try (InputStream in = BlockItems.class.getResourceAsStream(path)) {
            if (in == null) throw new IllegalStateException("missing resource " + path);
            return parse(new String(in.readAllBytes(), StandardCharsets.UTF_8));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    static BlockItems parse(String json) {
        JsonObject o = JsonParser.parseString(json).getAsJsonObject();
        Map<String, Entry> blocks = new HashMap<>();
        for (var e : o.getAsJsonObject("blocks").entrySet()) {
            JsonObject b = e.getValue().getAsJsonObject();
            blocks.put(e.getKey(), new Entry(str(b.get("item")), str(b.get("rule"))));
        }
        Map<String, Integer> stacks = new HashMap<>();
        for (var e : o.getAsJsonObject("maxStack").entrySet()) stacks.put(e.getKey(), e.getValue().getAsInt());
        return new BlockItems(o.get("version").getAsString(), o.get("dataVersion").getAsInt(), blocks, stacks);
    }

    private static String str(JsonElement e) {
        return e == null || e.isJsonNull() ? null : e.getAsString();
    }

    // ---------- lookups ----------

    public String version() {
        return version;
    }

    public int dataVersion() {
        return dataVersion;
    }

    /** All block ids in the table. */
    public Map<String, Entry> blocks() {
        return Collections.unmodifiableMap(blocks);
    }

    /** The entry for a block id (after aliases), or null if the table does not know it. */
    public Entry entry(String blockId) {
        return blocks.get(resolve(blockId));
    }

    /** Max stack size of an item; 64 for ids the table does not know. */
    public int maxStack(String itemId) {
        Integer n = maxStack.get(itemId);
        if (n != null) return n;
        for (String v : VERSIONS) {
            BlockItems other = load(v);
            if (other != this && other.maxStack.containsKey(itemId)) return other.maxStack.get(itemId);
        }
        return 64;
    }

    /** Whether the item id exists in this version. */
    public boolean knowsItem(String itemId) {
        return maxStack.containsKey(itemId);
    }

    String resolve(String blockId) {
        String id = BlockState.normalizeId(blockId);
        if (blocks.containsKey(id)) return id;
        String alias = ALIASES.get(id);
        return alias != null && blocks.containsKey(alias) ? alias : id;
    }

    // ---------- materials ----------

    public MaterialList materials(Schematic schematic) {
        Map<String, Long> items = new TreeMap<>();
        Map<String, Long> fluids = new TreeMap<>();
        Map<String, Long> unknown = new TreeMap<>();
        long omitted = 0;
        for (var e : schematic.blockCounts().entrySet()) {
            BlockState state = e.getKey();
            long count = e.getValue();
            String id = resolve(state.name());
            if (SchematicReader.AIR.contains(id)) continue;
            Entry entry = blocks.get(id);
            if (entry == null) {
                // A block this table lacks may be in another bundled table (renamed, or removed later).
                for (String v : VERSIONS) {
                    BlockItems other = load(v);
                    if (other == this) continue;
                    Entry e2 = other.blocks.get(other.resolve(state.name()));
                    if (e2 != null) {
                        entry = e2;
                        id = other.resolve(state.name());
                        break;
                    }
                }
            }
            if (entry == null || (entry.item == null && entry.rule == null)) {
                String key = SchematicException.safe(id);
                if (unknown.containsKey(key) || unknown.size() < MAX_UNKNOWN) unknown.merge(key, count, Long::sum);
                else omitted += count;
                continue;
            }
            String rule = entry.rule == null ? "" : entry.rule;
            long per = 1; // items per block
            String extra = null;
            switch (rule.contains(":") ? rule.substring(0, rule.indexOf(':')) : rule) {
                case "ignore" -> per = 0;
                case "fluid" -> {
                    String level = state.property("level");
                    if (level == null || level.equals("0")) fluids.merge(FLUID_BUCKETS.getOrDefault(id, id), count, Long::sum);
                    per = 0;
                }
                case "lower" -> per = "upper".equals(state.property("half")) ? 0 : 1;
                case "head" -> per = "foot".equals(state.property("part")) ? 0 : 1;
                case "slab" -> per = "double".equals(state.property("type")) ? 2 : 1;
                case "amount" -> per = amount(state.property(rule.substring(rule.indexOf(':') + 1)));
                case "pot", "with" -> extra = rule.substring(rule.indexOf(':') + 1);
                default -> { }
            }
            if (per > 0 && entry.item != null) items.merge(entry.item, per * count, Long::sum);
            if (extra != null) items.merge(extra, count, Long::sum);
        }
        Map<String, Long> containers = new TreeMap<>(schematic.containerItems());
        return new MaterialList(version, Collections.unmodifiableMap(items), Collections.unmodifiableMap(fluids),
            Collections.unmodifiableMap(containers), Collections.unmodifiableMap(unknown), omitted);
    }

    /** An amount property value (1-64); 1 when missing or not a number. */
    private static long amount(String v) {
        if (v == null) return 1;
        try {
            int n = Integer.parseInt(v.trim());
            return n < 1 ? 1 : Math.min(n, 64);
        } catch (NumberFormatException e) {
            return 1;
        }
    }

    // ---------- versions ----------

    static int[] parts(String v) {
        String[] s = (v == null ? "" : v.trim()).split("\\.");
        int[] out = new int[3];
        for (int i = 0; i < Math.min(3, s.length); i++) {
            try {
                out[i] = Integer.parseInt(s[i].replaceAll("[^0-9].*", ""));
            } catch (NumberFormatException e) {
                out[i] = 0;
            }
        }
        return out;
    }

    static int compare(int[] a, int[] b) {
        for (int i = 0; i < 3; i++) if (a[i] != b[i]) return Integer.compare(a[i], b[i]);
        return 0;
    }
}
